// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAuditEvents List the organisation's audit events, newest first
	// (GET /audit-events)
	ListAuditEvents(ctx context.Context, request ListAuditEventsRequestObject) (ListAuditEventsResponseObject, error)
	// GetInvitationPreview Look up an invitation by its token
	// (GET /auth/invitations/{token})
	GetInvitationPreview(ctx context.Context, request GetInvitationPreviewRequestObject) (GetInvitationPreviewResponseObject, error)
	// AcceptInvitation Accept an invitation, creating the account if needed, and sign in
	// (POST /auth/invitations/{token}/accept)
	AcceptInvitation(ctx context.Context, request AcceptInvitationRequestObject) (AcceptInvitationResponseObject, error)
	// Login Sign in with email and password
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Sign out and revoke the current session
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// CompletePasswordReset Set a new password using a reset token
	// (POST /auth/password-reset/complete)
	CompletePasswordReset(ctx context.Context, request CompletePasswordResetRequestObject) (CompletePasswordResetResponseObject, error)
	// RequestPasswordReset Email a password reset link (same response whether or not the account exists)
	// (POST /auth/password-reset/request)
	RequestPasswordReset(ctx context.Context, request RequestPasswordResetRequestObject) (RequestPasswordResetResponseObject, error)
	// GetSession Current user, memberships, active organisation/location and permissions
	// (GET /auth/session)
	GetSession(ctx context.Context, request GetSessionRequestObject) (GetSessionResponseObject, error)
	// SwitchLocation Change the session's active location (null = all accessible locations)
	// (POST /auth/session/location)
	SwitchLocation(ctx context.Context, request SwitchLocationRequestObject) (SwitchLocationResponseObject, error)
	// SwitchOrganisation Change the session's active organisation
	// (POST /auth/session/organisation)
	SwitchOrganisation(ctx context.Context, request SwitchOrganisationRequestObject) (SwitchOrganisationResponseObject, error)
	// ListInvitations List pending invitations
	// (GET /invitations)
	ListInvitations(ctx context.Context, request ListInvitationsRequestObject) (ListInvitationsResponseObject, error)
	// CreateInvitation Invite a person by email
	// (POST /invitations)
	CreateInvitation(ctx context.Context, request CreateInvitationRequestObject) (CreateInvitationResponseObject, error)

	// (POST /invitations/{invitationId}/revoke)
	RevokeInvitation(ctx context.Context, request RevokeInvitationRequestObject) (RevokeInvitationResponseObject, error)
	// ListLocations List locations the current member can access
	// (GET /locations)
	ListLocations(ctx context.Context, request ListLocationsRequestObject) (ListLocationsResponseObject, error)
	// CreateLocation Create a location
	// (POST /locations)
	CreateLocation(ctx context.Context, request CreateLocationRequestObject) (CreateLocationResponseObject, error)

	// (GET /locations/{locationId})
	GetLocation(ctx context.Context, request GetLocationRequestObject) (GetLocationResponseObject, error)

	// (PATCH /locations/{locationId})
	UpdateLocation(ctx context.Context, request UpdateLocationRequestObject) (UpdateLocationResponseObject, error)

	// (POST /locations/{locationId}/archive)
	ArchiveLocation(ctx context.Context, request ArchiveLocationRequestObject) (ArchiveLocationResponseObject, error)

	// (GET /members)
	ListMembers(ctx context.Context, request ListMembersRequestObject) (ListMembersResponseObject, error)
	// UpdateMember Change a member's role and/or location restrictions
	// (PATCH /members/{memberId})
	UpdateMember(ctx context.Context, request UpdateMemberRequestObject) (UpdateMemberResponseObject, error)

	// (POST /members/{memberId}/deactivate)
	DeactivateMember(ctx context.Context, request DeactivateMemberRequestObject) (DeactivateMemberResponseObject, error)

	// (POST /members/{memberId}/reactivate)
	ReactivateMember(ctx context.Context, request ReactivateMemberRequestObject) (ReactivateMemberResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

